import {weddings,faqs,reviews,films,articles} from '/content.js';

const main=document.querySelector('#content');
const footer=document.querySelector('#footer');
const menu=document.querySelector('#site-menu');
const menuToggle=document.querySelector('.menu-toggle');
const lightbox=document.querySelector('#lightbox');
const player=document.querySelector('#film-player');
const curtain=document.querySelector('.page-curtain');
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const photo=(n)=>`/assets/photo-${String((n-1)%15+1).padStart(2,'0')}.jpg`;
const image=(n,alt='',extra='')=>`<img src="${photo(n)}" alt="${alt}" ${extra}>`;
const link=(path,text,cls='line-link')=>`<a class="${cls}" data-link href="${path}">${text}</a>`;
const borderLink=(path,text)=>link(path,`<span>${text}</span><b aria-hidden="true">→</b>`,'border-link');
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

function hero(title,description,n=1,cls=''){
 return `<section class="hero ${cls}"><div class="hero-photo">${image(n,'Wedding photography by Square Studio','fetchpriority="high"')}</div><h1>${title}</h1><p class="hero-description">${description}</p></section>`;
}
function enquiry(contact=false){
return `<section class="enquiry ${contact?'contact-page':''}" id="enquiry"><h2 class="reveal">Hey There!</h2><form class="enquiry-form"><div class="sentence-fields"><label for="name">MY NAME IS</label><input id="name" name="name" placeholder="Jane Smith" autocomplete="name" required maxlength="100"><label for="event">AND I AM PLANNING A</label><input id="event" name="event" placeholder="Wedding" required maxlength="100"><label for="location">IN</label><input id="location" name="location" placeholder="Thailand" required maxlength="100"><label for="date">ON</label><input id="date" name="date" type="date" required><label for="planner">MY WEDDING PLANNER IS</label><input id="planner" name="planner" placeholder="Your planner" maxlength="100"><label for="instagram">AND I'M</label><input id="instagram" name="instagram" placeholder="@Jane" maxlength="100"><span>ON INSTAGRAM</span></div><div class="contact-fields"><div><label for="email">PLEASE EMAIL ME YOUR PROPOSAL AT</label><input id="email" name="email" type="email" autocomplete="email" placeholder="jane@example.com" required maxlength="200"></div><div><label for="phone">AND CONTACT ME VIA MOBILE AT</label><input id="phone" name="phone" type="tel" autocomplete="tel" placeholder="+91 9898989898" required maxlength="30"></div></div><button class="submit-button" type="submit">Submit</button><p class="form-status" role="status" hidden></p><p class="form-fineprint">By submitting this form, you agree to the ${link('/term-condition','Terms & Conditions, Privacy Policy,','')} and service guidelines of Square Studio Photography & Films.</p></form></section>`;
}
function weddingCard(w){return `<a class="wedding-card" data-link href="/real-weddings/${w.slug}"><p class="names">${w.names}</p><figure class="card-photo">${image(w.photo,`${w.names}, ${w.place}`,'loading="lazy"')}</figure><h3>${w.names} – ${w.description}</h3><div class="wedding-meta"><p class="place">${w.place}</p><p class="year">${w.year}</p></div></a>`;}
function insta(){return `<section class="instagram-section"><h2 class="reveal">Discover us on instagram</h2><div class="instagram-grid">${[3,5,8,11].map(n=>`<a href="https://www.instagram.com/" target="_blank" rel="noopener noreferrer" aria-label="Discover Square Studio on Instagram">${image(n,'Wedding inspiration','loading="lazy"')}</a>`).join('')}</div></section>`;}
function faq(){return `<section class="faq-section"><div class="faq-heading"><h2>FAQ :</h2><p>All your answers here</p></div><div class="faq-list">${faqs.map(([q,a])=>`<details><summary>${q}</summary><div class="faq-answer"><p>${a}</p></div></details>`).join('')}</div></section>`;}
function reviewCard(r){return `<a class="review-card" data-link href="/testimonials"><figure class="review-avatar">${image(r.photo,r.names,'loading="lazy"')}</figure><p>${r.quote}</p><span class="review-credit">${r.names} – ${r.place}</span></a>`;}
function reviewSection(){return `<section class="reviews-section"><p class="eyebrow">Smiles and Stories from</p><h2>My Clients</h2><div class="review-marquee">${[...reviews.slice(0,4),...reviews.slice(0,4)].map(reviewCard).join('')}</div>${link('/testimonials','View All Reviews')}</section>`;}
function footerContent(){return `<div class="footer-contact"><a class="brand footer-brand" data-link href="/" aria-label="Square Studio home"><span class="brand-mark"><span>S</span><span>S</span></span><span class="brand-name">SQUARE STUDIO</span></a><p>New Delhi & Gurgaon, India</p><p><a href="mailto:hello@squarestudio.example">hello@squarestudio.example</a></p></div><nav class="footer-nav" aria-label="Footer navigation"><div>${[['Real Weddings','real-weddings'],['Films','films'],['Portfolio','portfolio']].map(([t,p])=>link('/'+p,t,'')).join('')}</div><div>${[['About Us','about-us'],['Contact Us','contact-us'],['Work With Us','job']].map(([t,p])=>link('/'+p,t,'')).join('')}<a href="https://www.instagram.com/" target="_blank" rel="noopener noreferrer">Instagram</a><a href="https://www.youtube.com/" target="_blank" rel="noopener noreferrer">Youtube</a></div></nav><p class="footer-copy">© ${new Date().getFullYear()} Square Studio Photography & Films. ${link('/term-condition','Terms, Privacy Policy & Disclaimer.','')}</p>`;}
function gallery(numbers,cls=''){return `<section class="gallery ${cls}" aria-label="Photography gallery">${numbers.map((n,i)=>`<button class="gallery-image reveal" data-photo="${n}" data-index="${i}" aria-label="View photograph ${i+1}">${image(n,'Wedding editorial '+(i+1),'loading="lazy"')}</button>`).join('')}</section>`;}
function home(){
const cards=Array.from({length:15},(_,i)=>`<figure class="collage-photo ${i===7?'collage-main':''}" data-col="${i%5-2}" data-row="${Math.floor(i/5)-1}">${image([1,2,3,4,5,6,9,8,10,11,12,7,4,5,2][i],'Wedding editorial','loading="lazy"')}</figure>`).join('');
return `${hero('Refined Wedding Editorials','Square Studio is a wedding photography & film company located in New Delhi, India. We specialise in candid wedding photography and cinematography for destination weddings worldwide.')}<section class="quote-section"><h2>The Best Thing About Memories, Is Making Them.</h2><p>~ SQUARE STUDIO</p></section><section class="collage-scroll" aria-label="Our photography"><div class="collage-sticky"><div class="collage-grid">${cards}</div></div></section><div class="portfolio-cta">${link('/portfolio','EXPLORE OUR PORTFOLIO')}</div><section class="dark"><div class="wedding-heading"><h2>Our <em>real</em> weddings</h2>${link('/real-weddings','SEE ALL WEDDINGS')}</div><div class="wedding-scroll"><div class="wedding-sticky"><div class="wedding-track">${weddings.slice(0,4).map(weddingCard).join('')}</div></div></div><section class="philosophy"><div><h2 class="reveal">Guided by <em>emotion.</em> Grounded in <em>elegance.</em></h2><p>Square Studio Photography & Films captures destination weddings across India and beyond, with vibrant images and heartfelt, cinematic films full of energy and emotion.</p>${link('/about-us','Know About Us')}</div><figure class="philosophy-photo reveal">${image(3,'A quiet moment, beautifully remembered','loading="lazy"')}</figure></section></section>${enquiry()}<section class="studio-intro"><figure class="reveal">${image(13,'The Square Studio creative team','loading="lazy"')}</figure><div class="intro-copy"><p>Square Studio Photography & Films is a collective of artists documenting destination weddings in India and around the world. Our photographs are vibrant, our films heartfelt, and our approach always personal.</p><p>From the first conversation to the last frame, we take the time to understand your celebration. Our team brings together photographers, filmmakers, editors, and aerial artists with a shared love for honest storytelling.</p><p>We find inspiration in the places we travel, the people we meet, and the small moments that make every story different.</p><p>Here to capture the feeling, as well as the frame.</p>${borderLink('/job','Work with us')}</div></section>${reviewSection()}${insta()}${faq()}`;
}
function portfolio(){return `${hero('Portfolio','Explore our portfolio of Indian and destination weddings — where every frame tells a story of style, celebration, and timeless elegance.',5,'portfolio-hero')}${gallery([1,3,5,8,9,2,4,6,10,11,12,7])}${enquiry()}${insta()}`;}
function weddingPage(){return `${hero('Real Weddings','Explore our portfolio of Indian and destination weddings — where every frame tells a story of style, celebration, and timeless elegance.',8,'center-title')}<section class="wedding-list">${weddings.map(weddingCard).join('')}</section>${enquiry()}${insta()}`;}
function filmRow(f){return `<article class="film-row" data-search="${escapeHTML((f.title+' '+f.names+' '+f.type+' '+f.place).toLowerCase())}"><button class="film-poster" data-film aria-label="Play ${f.title}">${image(f.photo,f.title,'loading="lazy"')}<span class="play-symbol" aria-hidden="true">▶</span></button><div class="film-details"><span class="film-tag">${f.type}</span><h3>${f.title}</h3><p>${f.description}</p><p class="film-couple">${f.names}</p><p class="film-year">${f.year}</p></div></article>`;}
function filmsPage(){return `${hero('Films','Experience our wedding films — crafted with heart, style, and story. From Indian traditions to destination vows, each film captures the spirit of your celebration with timeless cinematic beauty.',2,'films-hero center-title')}<section class="search-section"><h2>Films</h2><label class="sr-only" for="film-search">Search wedding films</label><input class="film-search" id="film-search" type="search" placeholder="Search Wedding Films, Performances & Events"></section><section class="films-list">${films.map(filmRow).join('')}<p class="no-results" role="status" hidden>No films match your search. Try a couple, destination, or film type.</p></section>${enquiry()}${insta()}`;}
function aboutPage(){return `<section class="about-hero"><figure>${image(13,'Square Studio creative team','fetchpriority="high"')}</figure><h1>Square</h1><p class="about-last">Studio</p></section><section class="about-body"><h2 class="reveal">Square Studio</h2><p>We are a collective of photographers and filmmakers, brought together by a love of celebrations and the stories behind them. We make photographs that feel alive and films that take you back to how it felt.</p><p>Our work brings editorial composition together with spontaneous, honest moments. From intimate ceremonies to destination celebrations, we approach every wedding with curiosity, care, and a fresh perspective.</p><p>Based in New Delhi, we travel wherever your story takes us. A small creative team, a shared point of view, and an attention to the details that make a celebration your own.</p><div class="team-row"><figure>${image(15,'Creative director, Square Studio','loading="lazy"')}</figure><div><h2>Arjun Mehta</h2><p>Creative Director & Photographer</p><p>Arjun finds the story in the moments between the moments. With an eye for light and a love of travel, he brings a thoughtful, personal approach to every celebration.</p></div></div><div class="team-row"><figure>${image(14,'Film director, Square Studio','loading="lazy"')}</figure><div><h2>Maya Kapoor</h2><p>Film Director & Storyteller</p><p>Maya turns fleeting moments into films full of feeling. Her approach is quiet and instinctive, shaped by the people and places in every story.</p></div></div></section><section class="clients-strip"><h2>Our Clients</h2><div class="client-names"><span>THE GRAND</span><span>Maison</span><span>PALACE HOTELS</span><span>THE COLLECTIVE</span></div></section><section class="clients-strip dark"><h2>Honors That Speak</h2><div class="client-names"><span>Photography</span><span>Storytelling</span><span>Film</span><span>Creative Direction</span></div></section>${enquiry()}${insta()}`;}
function testimonials(){return `<section class="testimonial-page"><h1 class="page-title">Testimonials</h1><div class="testimonial-grid">${reviews.map(r=>`<article class="testimonial-item"><figure>${image(r.photo,r.names,'loading="lazy"')}</figure><div><blockquote>${r.quote}</blockquote><p>${r.names}<br><em>${r.place}</em></p></div></article>`).join('')}</div></section>${enquiry()}${insta()}`;}
function story(slug){const w=weddings.find(w=>w.slug===slug);if(!w)return missing();return `<section class="story-hero"><figure>${image(w.photo,w.names,'fetchpriority="high"')}</figure><h1>${w.names} – ${w.description}</h1></section><section class="story-copy"><h2>A celebration of love, beautifully remembered.</h2><p>In ${w.place}, ${w.names} brought their closest people together for a celebration filled with warmth, laughter, and little moments to remember. From the quiet anticipation to the energy of the dance floor, we followed their story as it unfolded.</p><p>Every photograph holds a piece of that feeling. The meaningful details, the unscripted smiles, the joy of being together.</p></section>${gallery(Array.from({length:16},(_,i)=>(i+w.photo-1)%12+1),'story-gallery')}<section class="story-copy"><h2>The beauty was in the moments they shared.</h2></section><div class="more-weddings"><h2>More real weddings</h2></div><section class="wedding-list">${weddings.filter(x=>x!==w).slice(0,2).map(weddingCard).join('')}</section>${enquiry()}${insta()}`;}
function jobs(){return `<section class="job-page"><h1 class="page-title">Work With Us</h1><h2>Fill Out The Form</h2><form class="job-form"><label>Your name<input name="name" autocomplete="name" required></label><label>Email address<input name="email" type="email" autocomplete="email" required></label><label>Phone number<input name="phone" type="tel" autocomplete="tel" required></label><label>Your discipline<select name="role" required><option value="">Choose a role</option><option>Photography</option><option>Filmmaking</option><option>Editing</option><option>Production</option></select></label><label class="full-field">Portfolio link<input name="portfolio" type="url" placeholder="https://" required></label><label class="full-field">Tell us about yourself<textarea name="message" rows="4" required></textarea></label><div class="full-field"><button class="submit-button" type="submit">Submit</button><p class="form-status" role="status" hidden></p></div></form><p>For photographers — a strong understanding of professional cameras, natural and off-camera lighting, data backups, Lightroom, and Photoshop.</p><p>For filmmakers — an eye for storytelling, sound knowledge of camera and audio equipment, and experience filming live events.</p><p>For editors — experience with editing, colour grading, and bringing a story together with care.</p></section>${insta()}`;}
function blogPage(){return `<section class="blog-page"><h1 class="page-title">Blogs</h1><div class="blog-grid">${articles.map(a=>`<a class="blog-card" data-link href="/blogs/${a.slug}"><figure>${image(a.photo,a.title,'loading="lazy"')}</figure><h2>${a.title}</h2><p>${a.category} · ${a.date}</p></a>`).join('')}</div></section>${insta()}`;}
function articlePage(slug){const a=articles.find(a=>a.slug===slug);if(!a)return missing();return `${hero(a.title,'Stories, inspiration, and a closer look at how we see celebrations.',a.photo,'portfolio-hero')}<article class="story-copy"><h2>${a.title}</h2>${a.paragraphs.map(p=>`<p style="margin-bottom:28px">${p}</p>`).join('')}</article>${enquiry()}`;}
function legal(){return `<article class="legal-page"><h1 class="page-title">Terms & Privacy</h1><h2>About this preview</h2><p>This Square Studio website is a demonstration using placeholder studio details, photographs, and films. The images do not represent commissioned work by Square Studio. Contact details are placeholders.</p><h2>Enquiries</h2><p>The enquiry and application forms validate your entries and offer a downloadable copy for your review. They do not send messages or store information on a server. A booking is only confirmed after a separate written agreement.</p><h2>Privacy</h2><p>Form details stay in this browser session and are used only to create the file you choose to download. This demonstration does not use advertising trackers or analytics cookies.</p><h2>External links</h2><p>Social links lead to the corresponding platform home pages until Square Studio’s own profiles are supplied.</p><h2>Contact</h2><p>Studio contact information and full booking policies will be added before the site launches.</p></article>`;}
function missing(){return `<section class="legal-page"><h1 class="page-title">Page not found.</h1><p>Let's take you back to the beginning.</p>${borderLink('/','Back to home')}</section>`;}

let observer;
function render(){
 observer?.disconnect();
 const path=decodeURIComponent(location.pathname).replace(/\/$/,'')||'/';let markup,title;
 const routes={'/':[home,'Wedding Photography & Films'],'/portfolio':[portfolio,'Portfolio'],'/real-weddings':[weddingPage,'Real Weddings'],'/films':[filmsPage,'Films'],'/about-us':[aboutPage,'About Us'],'/contact-us':[()=>enquiry(true)+insta()+faq(),'Contact Us'],'/testimonials':[testimonials,'Testimonials'],'/job':[jobs,'Work With Us'],'/blogs':[blogPage,'Blogs'],'/term-condition':[legal,'Terms & Privacy']};
 if(routes[path]){markup=routes[path][0]();title=routes[path][1];}
 else if(path.startsWith('/real-weddings/')){markup=story(path.split('/')[2]);title=weddings.find(w=>w.slug===path.split('/')[2])?.names||'Wedding Story';}
 else if(path.startsWith('/blogs/')){markup=articlePage(path.split('/')[2]);title=articles.find(a=>a.slug===path.split('/')[2])?.title||'Journal';}
 else {markup=missing();title='Page not found';}
 main.innerHTML=markup;footer.innerHTML=footerContent();document.title=`Square Studio | ${title}`;
 observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});
 document.querySelectorAll('.reveal').forEach(e=>observer.observe(e));
 document.querySelectorAll('.enquiry-form,.job-form').forEach(form=>form.addEventListener('submit',submitForm));
 document.querySelectorAll('.faq-list details').forEach(item=>item.addEventListener('toggle',()=>{if(item.open)item.parentElement.querySelectorAll('details').forEach(other=>{if(other!==item)other.open=false})}));
 const search=document.querySelector('#film-search');if(search)search.addEventListener('input',()=>{const q=search.value.trim().toLowerCase();let count=0;document.querySelectorAll('.film-row').forEach(row=>{row.hidden=!row.dataset.search.includes(q);if(!row.hidden)count++});document.querySelector('.no-results').hidden=count>0});
 updateMotion();
}
function submitForm(e){
 e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;
 const status=form.querySelector('.form-status');status.hidden=false;status.replaceChildren();
 const message=document.createElement('span');message.textContent='Your details are ready to review. This preview does not send enquiries. ';status.append(message);
 const button=document.createElement('button');button.type='button';button.textContent='Download your details';button.style.cssText='border:0;border-bottom:1px solid;background:none;padding:3px 0;font:inherit';
 const values=Object.fromEntries(new FormData(form));button.addEventListener('click',()=>{const text='SQUARE STUDIO\n\n'+Object.entries(values).map(([k,v])=>`${k}: ${v}`).join('\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=form.classList.contains('job-form')?'square-studio-application.txt':'square-studio-enquiry.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});status.append(button);
}
function openMenu(){menu.classList.remove('closing');menu.showModal();document.body.classList.add('locked');menuToggle.setAttribute('aria-expanded','true');menu.querySelector('.menu-close').focus();}
function closeMenu(immediate=false){menuToggle.setAttribute('aria-expanded','false');if(immediate||reduced){menu.close();document.body.classList.remove('locked');return}menu.classList.add('closing');setTimeout(()=>{menu.close();menu.classList.remove('closing');document.body.classList.remove('locked');menuToggle.focus()},450)}
menuToggle.addEventListener('click',openMenu);menu.querySelector('.menu-close').addEventListener('click',()=>closeMenu());menu.addEventListener('cancel',e=>{e.preventDefault();closeMenu()});menu.querySelectorAll('nav a').forEach((a,i)=>a.style.setProperty('--i',i));
let navigating=false;
async function navigate(href){if(navigating||href===location.pathname){closeMenu(true);return}navigating=true;closeMenu(true);curtain.className='page-curtain cover';if(!reduced)await new Promise(r=>setTimeout(r,350));history.pushState({},'',href);window.scrollTo({top:0,behavior:'instant'});render();main.setAttribute('tabindex','-1');main.focus({preventScroll:true});curtain.className='page-curtain uncover';if(!reduced)await new Promise(r=>setTimeout(r,650));curtain.className='page-curtain';navigating=false;}
document.addEventListener('click',e=>{const a=e.target.closest('a[data-link]');if(a&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey&&!e.altKey&&e.button===0){e.preventDefault();navigate(a.getAttribute('href'))}const img=e.target.closest('[data-photo]');if(img){const gallery=img.closest('.gallery');viewerImages=[...gallery.querySelectorAll('[data-photo]')].map(b=>({src:photo(Number(b.dataset.photo)),alt:b.querySelector('img').alt}));viewerIndex=Number(img.dataset.index);showPhoto();lightbox.showModal();document.body.classList.add('locked')}if(e.target.closest('[data-film]')){player.showModal();document.body.classList.add('locked');player.querySelector('video').play().catch(()=>{})}});
addEventListener('popstate',()=>{closeMenu(true);window.scrollTo({top:0,behavior:'instant'});render()});
let viewerImages=[],viewerIndex=0;
function showPhoto(){const img=lightbox.querySelector('img');const entry=viewerImages[viewerIndex];img.src=entry.src;img.alt=entry.alt;lightbox.querySelector('figcaption').textContent=`${viewerIndex+1} / ${viewerImages.length}`;}
lightbox.querySelector('.viewer-prev').addEventListener('click',()=>{viewerIndex=(viewerIndex-1+viewerImages.length)%viewerImages.length;showPhoto()});lightbox.querySelector('.viewer-next').addEventListener('click',()=>{viewerIndex=(viewerIndex+1)%viewerImages.length;showPhoto()});
lightbox.addEventListener('keydown',e=>{if(e.key==='ArrowLeft')lightbox.querySelector('.viewer-prev').click();if(e.key==='ArrowRight')lightbox.querySelector('.viewer-next').click()});
for(const dialog of [lightbox,player]){dialog.querySelector('.viewer-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{document.body.classList.remove('locked');if(dialog===player){const video=player.querySelector('video');video.pause();video.currentTime=0;}});dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});}
function clamp(n,a=0,b=1){return Math.max(a,Math.min(b,n))}
function updateMotion(){
 const width=innerWidth,height=innerHeight;
 const collage=document.querySelector('.collage-scroll');
 if(collage){const rect=collage.getBoundingClientRect();const distance=Math.max(1,rect.height-height);const p=reduced?1:clamp(-rect.top/distance);const spread=1-Math.pow(1-clamp((p-.02)/.75),3);const mobile=width<=809;const item=width<=480?75:mobile?110:width<1200?145:width>=1600?230:200;const spacingX=mobile?Math.min(width/4.7,item+20):item+Math.max(25,width*.029);const spacingY=width<=480?120:mobile?172:item*1.26+36;
 collage.querySelectorAll('.collage-photo').forEach(el=>{const col=+el.dataset.col,row=+el.dataset.row,isMain=el.classList.contains('collage-main');const scale=isMain?2-spread: .5+.5*spread;el.style.transform=`translate3d(${col*spacingX*spread}px,${row*spacingY*spread}px,0) scale(${scale})`;el.style.opacity=isMain?1:clamp((spread-.01)*1.8);});}
 const scroll=document.querySelector('.wedding-scroll');if(scroll&&width>809){const track=scroll.querySelector('.wedding-track');const rect=scroll.getBoundingClientRect();const p=clamp(-rect.top/(rect.height-height));const distance=track.scrollWidth-width+100;const start=width*.44;track.style.transform=`translate3d(${start-(distance+start)*p}px,0,0)`;}
 const heroImage=document.querySelector('.hero-photo');if(heroImage&&!reduced){const hero=heroImage.parentElement.getBoundingClientRect();if(hero.bottom>0)heroImage.style.translate=`0 ${clamp(-hero.top/4,0,height*.3)}px`;}
}
let frame=false;addEventListener('scroll',()=>{if(!frame){requestAnimationFrame(()=>{updateMotion();frame=false});frame=true}},{passive:true});addEventListener('resize',updateMotion);
render();
